@namespace sv_354deb845e0b46c8a12ecbc1489e546d.Components.Chat

<div class="channel-item @(IsActive ? "active" : "")" @onclick="OnClick">
    <div class="channel-name"># @Channel.Name</div>
    <div class="channel-desc">@Channel.Description</div>
    @if (Channel.UnreadCount > 0)
    {
        <span class="badge bg-primary rounded-pill unread-badge">@Channel.UnreadCount</span>
    }
</div>

@code {
    [Parameter, EditorRequired] public Channel Channel { get; set; } = default!;
    [Parameter] public bool IsActive { get; set; }
    [Parameter] public EventCallback OnClick { get; set; }
}

@namespace sv_354deb845e0b46c8a12ecbc1489e546d.Components.Chat

<div class="channel-sidebar">
    <div class="sidebar-header">
        <h5>Channels</h5>
    </div>
    <div class="channel-list">
        @foreach (var channel in Channels)
        {
            <ChannelItem Channel="channel"
                         IsActive="channel.Id == SelectedChannelId"
                         OnClick="() => OnChannelSelected.InvokeAsync(channel.Id)" />
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public List<Channel> Channels { get; set; } = new();
    [Parameter] public int SelectedChannelId { get; set; }
    [Parameter] public EventCallback<int> OnChannelSelected { get; set; }
}

@namespace sv_354deb845e0b46c8a12ecbc1489e546d.Components.Chat

<div class="message-item" @onmouseenter="() => _showActions = true" @onmouseleave="() => _showActions = false">
    <div class="message-header">
        <span class="message-author">@Message.Author</span>
        <span class="message-time">@FormatRelativeTime(Message.SentAt)</span>
    </div>
    <div class="message-content">@Message.Content</div>

    @if (Message.Reactions.Count > 0)
    {
        <div class="message-reactions">
            @foreach (var reaction in Message.Reactions)
            {
                <span class="reaction-badge" @onclick="() => OnReact.InvokeAsync(reaction.Emoji)">
                    @reaction.Emoji @reaction.Users.Count
                </span>
            }
        </div>
    }

    @if (ReplyCount > 0)
    {
        <div class="thread-link" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">
            @ReplyCount @(ReplyCount == 1 ? "reply" : "replies")
        </div>
    }

    @if (_showActions && ShowActions)
    {
        <div class="message-actions">
            <button class="btn btn-sm btn-outline-secondary" @onclick="() => OnOpenThread.InvokeAsync(Message.Id)">Reply</button>
            <div class="emoji-picker-inline">
                @foreach (var emoji in _commonEmojis)
                {
                    <button class="btn btn-sm btn-outline-secondary emoji-btn" @onclick="() => OnReact.InvokeAsync(emoji)">@emoji</button>
                }
            </div>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired] public Message Message { get; set; } = default!;
    [Parameter] public int ReplyCount { get; set; }
    [Parameter] public bool ShowActions { get; set; } = true;
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<string> OnReact { get; set; }

    private bool _showActions;
    private static readonly string[] _commonEmojis = ["👍", "❤️", "😂", "🎉", "😮", "👀"];

    private static string FormatRelativeTime(DateTime sentAt)
    {
        var diff = DateTime.UtcNow - sentAt;
        if (diff.TotalMinutes < 1) return "just now";
        if (diff.TotalMinutes < 60) return $"{(int)diff.TotalMinutes} min ago";
        if (diff.TotalHours < 24) return $"{(int)diff.TotalHours} hr ago";
        return $"{(int)diff.TotalDays} days ago";
    }
}

@namespace sv_354deb845e0b46c8a12ecbc1489e546d.Components.Chat

<div class="message-input">
    <textarea class="form-control" rows="2" placeholder="@Placeholder" @bind="_text" @bind:event="oninput"
              @onkeydown="HandleKeyDown"></textarea>
    <button class="btn btn-primary mt-1" disabled="@string.IsNullOrWhiteSpace(_text)" @onclick="Send">@ButtonText</button>
</div>

@code {
    [Parameter] public string Placeholder { get; set; } = "Type a message...";
    [Parameter] public string ButtonText { get; set; } = "Send";
    [Parameter] public EventCallback<string> OnSend { get; set; }

    private string _text = string.Empty;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter" && !e.ShiftKey)
        {
            await Send();
        }
    }

    private async Task Send()
    {
        if (string.IsNullOrWhiteSpace(_text)) return;
        var content = _text.Trim();
        _text = string.Empty;
        await OnSend.InvokeAsync(content);
    }
}

@namespace sv_354deb845e0b46c8a12ecbc1489e546d.Components.Chat
@inject IJSRuntime JS

<div class="message-list" @ref="_scrollContainer" @onscroll="HandleScroll">
    @if (IsLoadingMore)
    {
        <div class="text-center p-2">
            <span class="spinner-border spinner-border-sm"></span> Loading...
        </div>
    }
    @foreach (var message in Messages)
    {
        <MessageItem Message="message"
                     ReplyCount="GetReplyCount(message.Id)"
                     OnOpenThread="OnOpenThread"
                     OnReact="(emoji) => OnReact.InvokeAsync((message.Id, emoji))" />
    }
</div>

@code {
    [Parameter, EditorRequired] public List<Message> Messages { get; set; } = new();
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }

    private ElementReference _scrollContainer;

    private int GetReplyCount(int messageId)
    {
        return ThreadSummaries.FirstOrDefault(t => t.RootMessageId == messageId)?.ReplyCount ?? 0;
    }

    private async Task HandleScroll()
    {
        var scrollTop = await JS.InvokeAsync<double>("eval", $"document.querySelector('.message-list')?.scrollTop ?? 1");
        if (scrollTop <= 0)
        {
            await OnLoadMore.InvokeAsync();
        }
    }
}

@namespace sv_354deb845e0b46c8a12ecbc1489e546d.Components.Chat

<div class="message-area">
    @if (CurrentChannel is not null)
    {
        <div class="message-area-header">
            <h5># @CurrentChannel.Name</h5>
            <p class="text-muted mb-0">@CurrentChannel.Description</p>
        </div>

        <MessageList Messages="Messages"
                     ThreadSummaries="ThreadSummaries"
                     IsLoadingMore="IsLoadingMore"
                     OnOpenThread="OnOpenThread"
                     OnReact="OnReact"
                     OnLoadMore="OnLoadMore" />

        <MessageInput Placeholder="@($"Message #{CurrentChannel.Name}")"
                      ButtonText="Send"
                      OnSend="OnSendMessage" />
    }
    else
    {
        <div class="d-flex align-items-center justify-content-center h-100 text-muted">
            Select a channel to start chatting
        </div>
    }
</div>

@code {
    [Parameter] public Channel? CurrentChannel { get; set; }
    [Parameter] public List<Message> Messages { get; set; } = new();
    [Parameter] public List<ThreadSummary> ThreadSummaries { get; set; } = new();
    [Parameter] public bool IsLoadingMore { get; set; }
    [Parameter] public EventCallback<int> OnOpenThread { get; set; }
    [Parameter] public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }
    [Parameter] public EventCallback OnLoadMore { get; set; }
    [Parameter] public EventCallback<string> OnSendMessage { get; set; }
}

@namespace sv_354deb845e0b46c8a12ecbc1489e546d.Components.Chat

<div class="thread-panel">
    <div class="thread-header">
        <h6>Thread</h6>
        <button class="btn btn-sm btn-outline-secondary" @onclick="OnClose">✕</button>
    </div>

    @if (RootMessage is not null)
    {
        <div class="thread-root-message">
            <MessageItem Message="RootMessage" ShowActions="false" />
        </div>

        <div class="thread-replies">
            @foreach (var reply in Replies)
            {
                <MessageItem Message="reply" ShowActions="false" />
            }
        </div>

        <MessageInput Placeholder="Reply in thread..."
                      ButtonText="Reply"
                      OnSend="OnSendReply" />
    }
</div>

@code {
    [Parameter] public Message? RootMessage { get; set; }
    [Parameter] public List<Message> Replies { get; set; } = new();
    [Parameter] public EventCallback OnClose { get; set; }
    [Parameter] public EventCallback<string> OnSendReply { get; set; }
}

