            <div class="emoji-picker-inline">
                @foreach (var emoji in _commonEmojis)
                {
                    <button class="btn btn-sm btn-outline-secondary emoji-btn" @onclick="() => OnReact.InvokeAsync(emoji)">@emoji</button>
                }
            </div>
        </div>
    }
