@page "/chat"
@namespace sv_354deb845e0b46c8a12ecbc1489e546d.Components.Pages
@using sv_354deb845e0b46c8a12ecbc1489e546d.Components.Chat
@inject IChatService ChatService
@rendermode InteractiveServer

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <ChannelSidebar Channels="_channels"
                    SelectedChannelId="_selectedChannelId"
                    OnChannelSelected="SelectChannel" />

    <div class="chat-main @(_isThreadOpen ? "thread-open" : "")">
        <MessageArea CurrentChannel="_currentChannel"
                     Messages="_messages"
                     ThreadSummaries="_threadSummaries"
                     IsLoadingMore="_isLoadingMore"
                     OnOpenThread="OpenThread"
                     OnReact="HandleReaction"
                     OnLoadMore="LoadMoreMessages"
                     OnSendMessage="SendMessage" />
    </div>

    @if (_isThreadOpen)
    {
        <ThreadPanel RootMessage="_threadRootMessage"
                     Replies="_threadReplies"
                     OnClose="CloseThread"
                     OnSendReply="SendThreadReply" />
    }
</div>

@code {
    private List<Channel> _channels = new();
    private int _selectedChannelId;
    private Channel? _currentChannel;
    private List<Message> _messages = new();
    private List<ThreadSummary> _threadSummaries = new();
    private bool _isLoadingMore;
    private const int PageSize = 30;

    private bool _isThreadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadReplies = new();

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await SelectChannel(_channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        _selectedChannelId = channelId;
        _currentChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        _threadSummaries = BuildThreadSummaries(_messages);
        await ChatService.MarkChannelReadAsync(channelId);
        CloseThreadSync();
    }

    private async Task LoadMoreMessages()
    {
        if (_isLoadingMore || _currentChannel is null) return;
        _isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(_currentChannel.Id, _messages.Count, PageSize);
        if (older.Count > 0)
        {
            _messages.InsertRange(0, older);
            _threadSummaries = BuildThreadSummaries(_messages);
        }
        _isLoadingMore = false;
    }

    private async Task SendMessage(string content)
    {
        if (_currentChannel is null) return;
        var msg = await ChatService.SendMessageAsync(_currentChannel.Id, content, null);
        _messages.Add(msg);
    }

    private async Task OpenThread(int messageId)
    {
        _threadRootMessage = _messages.FirstOrDefault(m => m.Id == messageId);
        if (_threadRootMessage is null) return;

        _threadReplies = await ChatService.GetThreadAsync(messageId);
        _isThreadOpen = true;
    }

    private Task CloseThread()
    {
        CloseThreadSync();
        return Task.CompletedTask;
    }

    private void CloseThreadSync()
    {
        _isThreadOpen = false;
        _threadRootMessage = null;
        _threadReplies = new();
    }

    private async Task SendThreadReply(string content)
    {
        if (_threadRootMessage is null || _currentChannel is null) return;
        var reply = await ChatService.SendMessageAsync(_currentChannel.Id, content, _threadRootMessage.Id);
        _threadReplies.Add(reply);
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);
    }

    private static List<ThreadSummary> BuildThreadSummaries(List<Message> messages)
    {
        var replies = messages.Where(m => m.ReplyToId.HasValue).ToList();
        return replies
            .GroupBy(m => m.ReplyToId!.Value)
            .Select(g => new ThreadSummary(g.Key, g.Count(), g.Max(m => m.SentAt)))
            .ToList();
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

/* Channel Sidebar */
.channel-sidebar {
    width: 20%;
    min-width: 200px;
    background-color: #2c2f33;
    color: #dcddde;
    display: flex;
    flex-direction: column;
    border-right: 1px solid #202225;
}

.sidebar-header {
    padding: 1rem;
    border-bottom: 1px solid #202225;
}

.sidebar-header h5 {
    margin: 0;
    color: #fff;
}

.channel-list {
    overflow-y: auto;
    flex: 1;
}

.channel-item {
    padding: 0.5rem 1rem;
    cursor: pointer;
    position: relative;
    border-left: 3px solid transparent;
    transition: background-color 0.15s;
}

.channel-item:hover {
    background-color: #36393f;
}

.channel-item.active {
    background-color: #393c43;
    border-left-color: #5865f2;
}

.channel-name {
    font-weight: 500;
    font-size: 0.95rem;
}

.channel-desc {
    font-size: 0.75rem;
    color: #8e9297;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
}

.unread-badge {
    position: absolute;
    top: 0.5rem;
    right: 0.75rem;
    font-size: 0.7rem;
}

/* Main Message Area */
.chat-main {
    flex: 1;
    display: flex;
    min-width: 0;
}

.chat-main.thread-open {
    flex: 0 0 55%;
}

.message-area {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-width: 0;
}

.message-area-header {
    padding: 0.75rem 1rem;
    border-bottom: 1px solid #e3e5e8;
    background: #fff;
}

.message-area-header h5 {
    margin-bottom: 0.25rem;
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 1rem;
    display: flex;
    flex-direction: column;
    gap: 0.25rem;
}

.message-item {
    padding: 0.5rem 0.75rem;
    border-radius: 4px;
    position: relative;
    transition: background-color 0.1s;
}

.message-item:hover {
    background-color: #f2f3f5;
}

.message-header {
