+    border-bottom: 1px solid #e3e5e8;
+    background: #fff;
+}
+
+.message-area-header h5 {
+    margin-bottom: 0.25rem;
+}
+
+.message-list {
+    flex: 1;
+    overflow-y: auto;
+    padding: 1rem;
+    display: flex;
+    flex-direction: column;
+    gap: 0.25rem;
+}
+
+.message-item {
+    padding: 0.5rem 0.75rem;
+    border-radius: 4px;
+    position: relative;
+    transition: background-color 0.1s;
+}
+
+.message-item:hover {
+    background-color: #f2f3f5;
+}
+
+.message-header {
+    display: flex;
+    align-items: baseline;
+    gap: 0.5rem;
+    margin-bottom: 0.2rem;
+}
+
+.message-author {
+    font-weight: 600;
+    font-size: 0.9rem;
+}
+
+.message-time {
+    font-size: 0.75rem;
+    color: #72767d;
+}
+
+.message-content {
+    font-size: 0.9rem;
+    line-height: 1.4;
+}
+
+.message-reactions {
+    display: flex;
+    gap: 0.25rem;
+    margin-top: 0.3rem;
+    flex-wrap: wrap;
+}
+
+.reaction-badge {
+    display: inline-flex;
+    align-items: center;
+    gap: 0.2rem;
+    padding: 0.15rem 0.4rem;
+    background: #e3e5e8;
+    border-radius: 12px;
+    font-size: 0.8rem;
+    cursor: pointer;
+    transition: background 0.15s;
+}
+
+.reaction-badge:hover {
+    background: #c8ccd0;
+}
+
+.thread-link {
+    font-size: 0.8rem;
+    color: #5865f2;
+    cursor: pointer;
+    margin-top: 0.25rem;
+    font-weight: 500;
+}
+
+.thread-link:hover {
+    text-decoration: underline;
+}
+
+.message-actions {
+    position: absolute;
+    top: -0.5rem;
+    right: 0.5rem;
+    display: flex;
+    gap: 0.25rem;
+    background: #fff;
+    border: 1px solid #e3e5e8;
+    border-radius: 4px;
+    padding: 0.2rem;
+    box-shadow: 0 1px 4px rgba(0,0,0,0.1);
+    z-index: 10;
+}
+
+.emoji-picker-inline {
+    display: flex;
+    gap: 0.1rem;
+}
+
+.emoji-btn {
+    padding: 0.15rem 0.3rem;
+    font-size: 0.85rem;
+    line-height: 1;
+}
+
+.message-input {
+    padding: 0.75rem 1rem;
+    border-top: 1px solid #e3e5e8;
+    background: #fff;
+}
+
+.message-input textarea {
+    resize: none;
+}
+
+/* Thread Panel */
+.thread-panel {
+    width: 25%;
+    min-width: 280px;
+    border-left: 1px solid #e3e5e8;
+    display: flex;
+    flex-direction: column;
+    background: #fff;
+}
+
+.thread-header {
+    display: flex;
+    justify-content: space-between;
+    align-items: center;
+    padding: 0.75rem 1rem;
+    border-bottom: 1px solid #e3e5e8;
+}
+
+.thread-header h6 {
+    margin: 0;
+    font-weight: 600;
+}
+
+.thread-root-message {
+    padding: 0.5rem 1rem;
+    border-bottom: 1px solid #e3e5e8;
+    background: #f9fafb;
+}
+
+.thread-replies {
+    flex: 1;
+    overflow-y: auto;
+    padding: 0.5rem 1rem;
+    display: flex;
+    flex-direction: column;
+    gap: 0.25rem;
+}
+

